$labels = json_decode('{"navHome":"Lien Accueil","navCircuits":"Lien Nos circuits","navAbout":"Lien Esprit MIARADI","navFaq":"Lien FAQ","navQuote":"Bouton préparer le voyage","navQuoteButton":"Texte du bouton principal","heroEyebrow":"Petit titre du hero","heroTitle":"Titre principal","heroAccent":"Titre en italique","heroText":"Description du hero","heroButton":"Texte du bouton","storyEyebrow":"Petit titre","storyTitle":"Titre principal","storyAccent":"Titre en italique","storyLead":"Paragraphe mis en avant","storyP1":"Paragraphe 1","storyP2":"Paragraphe 2","storyP3":"Paragraphe 3","engagementEyebrow":"Petit titre","engagementTitle":"Titre principal","engagementAccent":"Accent du titre","engagementP1":"Paragraphe 1","engagementStrong":"Texte mis en avant","engagementP2":"Paragraphe 2","engagementP3":"Paragraphe 3","teamEyebrow":"Petit titre","teamTitle":"Titre principal","teamAccent":"Accent du titre","teamSize":"Nombre de personnes dans l’équipe","teamSizeLabel":"Libellé de l’équipe","partnerCount":"Nombre de partenaires","partnerCountLabel":"Libellé des partenaires","teamP1":"Paragraphe 1","teamP2":"Paragraphe 2","teamP3":"Paragraphe 3","closingText":"Texte de conclusion","closingLink":"Texte du lien","visionEyebrow":"Petit titre","visionTitle":"Titre principal","visionAccent":"Accent du titre","visionText":"Introduction","pillar1Title":"Pilier 1 — titre","pillar1Text":"Pilier 1 — description","pillar2Title":"Pilier 2 — titre","pillar2Text":"Pilier 2 — description","pillar3Title":"Pilier 3 — titre","pillar3Text":"Pilier 3 — description","visionCaption":"Légende de l’image","networkEyebrow":"Petit titre","networkTitle":"Titre principal","networkAccent":"Accent du titre","networkP1":"Paragraphe 1","networkP2":"Paragraphe 2","networkStrong":"Texte mis en avant","networkLink":"Texte du lien","faqEyebrow":"Petit titre","faqTitle":"Titre principal","faqAccent":"Accent du titre","faqIntro":"Texte d’introduction","faqLink":"Texte du lien","ctaEyebrow":"Petit titre","ctaTitle":"Titre principal","ctaAccent":"Accent du titre","ctaButton":"Texte du bouton","footerTagline":"Phrase sous le logo","footerHome":"Lien Accueil","footerCircuits":"Lien Nos circuits","footerContact":"Lien Contact","footerFaq":"Lien FAQ","footerBackTop":"Lien retour en haut"}', true, 512, JSON_THROW_ON_ERROR);
$textareas = json_decode('["storyLead","storyP1","storyP2","storyP3","engagementP1","engagementStrong","engagementP2","engagementP3","teamP1","teamP2","teamP3","closingText","visionText","pillar1Text","pillar2Text","pillar3Text","visionCaption","networkP1","networkP2","networkStrong","faqIntro","faq1A","faq2A","faq3A","faq4A","faq5A","faq6A","faq7A","faq8A","faq9A","faq10A","faq11A","faq12A","heroText"]', true, 512, JSON_THROW_ON_ERROR);
function field_label(string $key, array $labels): string {
  if (isset($labels[$key])) return $labels[$key];
  if (preg_match('/^faq(\d+)(Q|A)$/', $key, $m)) return 'Question '.$m[1].($m[2] === 'Q' ? ' — intitulé' : ' — réponse');
  return ucfirst(trim(preg_replace('/([a-z])([A-Z])/', '$1 $2', $key)));
}
