ght:0;background:#fffF;border-top:1px solid var(--line);backdrop-filter:blur(12px);padding:14px max(24px,calc((100vw - 1384px)/2));display:flex;align-items:center;gap:18px;z-index:10}.button{border:0;border-radius:999px;background:var(--red);color:#fff;font-weight:750;padding:13px 22px;cursor:pointer}.button:disabled{opacity:.6;cursor:wait}.status{color:var(--muted);font-size:13px}.helper{font-size:13px;color:var(--muted)}@media(max-width:850px){.shell{padding:22px 14px 100px}.top{align-items:start;flex-direction:column}.panel-layout{grid-template-columns:1fr}.panel-media{border-left:0;border-top:1px solid var(--line)}.fields{grid-template-columns:1fr}.field.wide{grid-column:auto}.sticky{padding:12px 14px;align-items:flex-start;flex-direction:column;gap:6px}}
