<div class="notice"><strong>Conseil :</strong> gardez les titres courts. Pour les questions fréquentes, modifiez l’intitulé et la réponse dans le même panneau afin de repérer facilement chaque paire.</div>
<form id="about-form">
<?php foreach ($groups as $groupName => $keys): ?>
<section class="panel"><div class="panel-layout"><div class="panel-copy"><div class="eyebrow">Modification du contenu</div><h2><?=htmlspecialchars($groupName, ENT_QUOTES, 'UTF-8')?></h2><p class="instructions"><?php if(str_starts_with($groupName,'FAQ')): ?>Chaque question et sa réponse sont regroupées ici. Les numéros et la mise en page restent automatiques.<?php elseif($groupName==='Hero et image principale'): ?>Cette zone est la première impression de la page. Modifiez les textes à gauche et remplacez la photo principale à droite.<?php elseif($groupName==='Vision du tourisme'): ?>Modifiez l’introduction et les trois piliers de la vision MIARADI. L’image et sa légende se trouvent à droite.<?php elseif($groupName==='Navigation'): ?>Modifiez les libellés affichés dans l’en-tête. Gardez-les courts pour préserver la lisibilité sur mobile.<?php else: ?>Les champs correspondent à cette section précise de la page publique. Modifiez les textes associés ensemble, puis enregistrez en bas de page.<?php endif; ?></p><div class="fields">
<?php foreach($keys as $key): $label=field_label($key,$labels); $isLong=in_array($key,$textareas,true)||preg_match('/^faq\d+A$/',$key); ?>
<label class="field <?=($isLong?'wide':'')?>"><?=htmlspecialchars($label,ENT_QUOTES,'UTF-8')?><?php if($isLong): ?><textarea name="<?=htmlspecialchars($key,ENT_QUOTES,'UTF-8')?>" rows="3"></textarea><?php else: ?><input name="<?=htmlspecialchars($key,ENT_QUOTES,'UTF-8')?>" maxlength="2000"><?php endif; ?></label>
<?php endforeach; ?>
</div></div><aside class="panel-media">
<?php if($groupName==='Hero et image principale'): ?><div class="media-heading"><h3>Image du hero</h3><p class="helper">Photo affichée derrière le titre de la page À propos.</p></div><article class="media-card"><img data-preview="heroImage" src="" alt=""><div class="media-body"><label class="field">Remplacer la photo<input type="file" data-upload="heroImage" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG ou WebP — 8 Mo maximum.</small></label><label class="field" style="margin-top:12px">Texte alternatif<input name="heroImageAlt" maxlength="250"></label><input type="hidden" name="heroImage"></div></article>
<?php elseif($groupName==='Vision du tourisme'): ?><div class="media-heading"><h3>Image de la vision</h3><p class="helper">Photo illustrative affichée sous les trois piliers, avec sa légende.</p></div><article class="media-card"><img data-preview="visionImage" src="" alt=""><div class="media-body"><label class="field">Remplacer la photo<input type="file" data-upload="visionImage" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG ou WebP — 8 Mo maximum.</small></label><label class="field" style="margin-top:12px">Texte alternatif<input name="visionImageAlt" maxlength="250"></label><input type="hidden" name="visionImage"></div></article>
<?php else: ?><div class="media-heading"><h3>Repère de modification</h3><p class="helper">Ce panneau modifie uniquement les textes de la section « <?=htmlspecialchars($groupName,ENT_QUOTES,'UTF-8')?> ». Les photos ne sont pas concernées par cette partie.</p></div><div class="notice">Repérez les champs par leur intitulé. Les questions et réponses de la FAQ sont présentées ensemble pour éviter les confusions.</div><?php endif; ?>
</aside></div></section>
<?php endforeach; ?>
<div class="sticky"><button class="button" id="save" type="submit">Enregistrer les modifications</button><span class="status" id="status" role="status" aria-live="polite">Chargement du contenu…</span></div>
</form></main>
<script>
const form=document.getElementById('about-form');
const csrf=<?=json_encode($csrf,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;
const statusNode=document.getElementById('status');
async function api(method='GET',data=null){const response=await fetch('../api/about-settings.php',{method,credentials:'same-origin',headers:{Accept:'application/json',...(data?{'Content-Type':'application/json','X-CSRF-Token':csrf}:{})},body:data?JSON.stringify(data):undefined});const payload=await response.json();if(!response.ok)throw new Error(payload.error?.message||'Une erreur est survenue.');return payload;}
async function uploadImage(slot,file){const node=statusNode;node.textContent='Téléversement de l’image…';const body=new FormData();body.append('slot',slot);body.append('image',file);const response=await fetch('../api/page-content-image.php',{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-Token':csrf},body});const payload=await response.json();if(!response.ok)throw new Error(payload.error?.message||'Échec du téléversement.');form.elements[slot].value=payload.data.path;document.querySelector('[data-preview="'+slot+'"]').src=payload.data.path;node.textContent='Image téléversée. Enregistrez pour appliquer le changement.';}
document.querySelectorAll('[data-upload]').forEach(input=>input.addEventListener('change',async()=>{const file=input.files?.[0];if(!file)return;try{await uploadImage(input.dataset.upload,file);}catch(error){statusNode.textContent=error.message;}}));
(async()=>{try{const payload=await api();for(const [key,value] of Object.entries(payload.data||{})){if(form.elements[key]&&form.elements[key].type!=='file')form.elements[key].value=value;}for(const slot of ['heroImage','visionImage']){const preview=document.querySelector('[data-preview="'+slot+'"]');if(preview)preview.src=payload.data?.[slot]||'';}statusNode.textContent='Contenu chargé.';}catch(error){statusNode.textContent=error.message;}})();
form.addEventListener('submit',async event=>{event.preventDefault();const button=document.getElementById('save');button.disabled=true;statusNode.textContent='Enregistrement…';const data=Object.fromEntries([...form.querySelectorAll('[name]')].filter(el=>el.type!=='file').map(el=>[el.name,el.value]));try{await api('PUT',data);statusNode.textContent='Modifications enregistrées. Actualisez la page publique pour voir les changements.';}catch(error){statusNode.textContent=error.message;}finally{button.disabled=false;}});
</script></body></html>